<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { brewApi } from '../api';
import ProductionPlanDetail from './ProductionPlanDetail.vue';
import JourneyDetailDialog from './JourneyDetailDialog.vue';
import PackagingPlanEditor from './PackagingPlanEditor.vue';
import { emptyPackagingDraft, packagingPayload } from '../plan-packaging';
const props = defineProps({ permissions: { type: Array, default: () => [] } });
const rows = ref([]), liquids = ref([]), orders = ref([]), loading = ref(false), error = ref(''), notice = ref(''), keyword = ref(''), tab = ref('tasks'), filter = ref('all'), selected = ref(null);
const creating = ref(false), sourceId = ref(''), sourceDetail = ref(null), sourceLoading = ref(false), draft = ref(emptyPackagingDraft()), saving = ref(false), editorError = ref('');
const releaseOrder = ref(null), confirmed = ref(false);
const canManage = computed(() => props.permissions.includes('plan.production.manage'));
const canRelease = computed(() => props.permissions.some(p=>['inventory.finished_goods.receive','base.master_data.manage'].includes(p)));
let sequence = 0, sourceSequence = 0;
const states = [{ key: 'all', label: '全部任务' }, { key: 'waiting', label: '等待酿造' }, { key: 'pending', label: '待执行' }, { key: 'running', label: '包装中' }, { key: 'done', label: '包装完成' }];
const unitLabel = value => ({can:'罐',bottle:'瓶',keg:'桶',box:'箱'})[value] || '件';
const number = value => Number(value || 0).toLocaleString('zh-CN', { maximumFractionDigits: 2 });
function state(row) {
  if (['cancelled','terminated'].includes(row.plan.state) || row.task?.state === 'cancelled') return 'closed';
  if (row.task?.state === 'done' || row.plan.packaging_plan?.status === 'packaged' || row.plan.packaging_plan?.execution) return 'done';
  if (row.task?.state === 'in_progress') return 'running';
  return row.plan.state === 'done' ? 'pending' : 'waiting';
}
const label = row => states.find(item => item.key === state(row))?.label || '已终止';
const ready = computed(() => liquids.value.filter(row => row.source_type === 'production' && ['raw_ready','awaiting_packaging'].includes(row.production_status)));
const candidates = computed(() => ready.value.filter(row => !rows.value.some(item => {
  if (String(item.plan.id) !== String(row.plan_id)) return false;
  return ['waiting','pending','running'].includes(state(item)) || state(item) === 'done' && !item.plan.packaging_plan?.execution?.packaging_order_id;
})));
const pendingRelease = computed(() => orders.value.filter(row => row.state === 'pending_release'));
const tabs = computed(() => [{key:'tasks',label:'包装任务',count:rows.value.length},{key:'raw',label:'待包装原液',count:candidates.value.length},{key:'release',label:'待放行',count:pendingRelease.value.length}]);
const matches = values => values.join(' ').toLowerCase().includes(keyword.value.toLowerCase());
const visible = computed(() => rows.value.filter(row => (filter.value === 'all' || state(row) === filter.value) && matches([row.plan.batch?.finished_product_code,row.plan.batch?.name,row.plan.name,row.plan.product?.name,row.plan.packaging_owner?.name,row.plan.factory?.name])));
const visibleRaw = computed(() => candidates.value.filter(row => matches([row.finished_product_code,row.product?.name,row.batch_name,row.factory?.name,row.tank])).sort((a,b) => String(b.production_date || '').localeCompare(String(a.production_date || '')) || Number(b.batch_id)-Number(a.batch_id)));
const visibleOrders = computed(() => pendingRelease.value.filter(row => matches([row.batch?.finished_product_code,row.name,row.product?.name,row.batch?.name,row.factory?.name])));
const source = computed(() => candidates.value.find(row => String(row.plan_id) === String(sourceId.value)));
const summary = computed(() => ({ pending: rows.value.filter(row=>state(row)==='pending').length, running: rows.value.filter(row=>state(row)==='running').length }));
function productionDate(value) { return new Date(/[zZ]|[+-]\d\d:\d\d$/.test(value) ? value : `${value}Z`).toLocaleString('zh-CN', {hour12:false,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}); }
function date(value) { if (!value) return '未安排'; return new Date(/[zZ]|[+-]\d\d:\d\d$/.test(value) ? value : `${value}Z`).toLocaleString('zh-CN', { hour12: false, month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }); }
const canExecute = row => row.task?.is_assignee && (row.task?.can_execute && ['pending','running'].includes(state(row)) || state(row)==='done' && !row.plan.packaging_plan?.execution?.packaging_order_id);
async function allPages(fetch) { const result=[]; for(let page=1;;page++){const items=await fetch({page,page_size:100});result.push(...items);if(items.length<100)return result;} }
async function load() {
  const request = ++sequence; loading.value = true; error.value = '';
  try {
    const [plans,stock,packagingOrders] = await Promise.all([
      allPages(p=>brewApi.listProductionPlans(p)),
      allPages(p=>brewApi.browseStock({...p,category:'semi_finished'}).then(r=>r.items)),
      allPages(p=>brewApi.listPackagingOrders(p))
    ]);
    const planned = plans.filter(plan => ['dispatched','in_progress','done','terminated'].includes(plan.state) && (plan.packaging_plan?.materials_only || plan.packaging_plan?.material_id || plan.packaging_plan?.packaging_id || plan.packaging_plan?.status === 'packaged'));
    const details = [], failures = [];
    for (let i = 0; i < planned.length; i += 6) {
      const group = planned.slice(i, i + 6);
      const results = await Promise.allSettled(group.map(plan => brewApi.getPlanProgress(plan.id)));
      results.forEach((result,index) => { if (result.status === 'fulfilled') { const detail = result.value; details.push({ plan: detail.plan, task: detail.tasks.slice().reverse().find(task => task.task_type === 'packaging' && task.state !== 'cancelled') }); } else failures.push(`${group[index].name}：${result.reason?.message || '加载失败'}`); });
    }
    if (request !== sequence) return;
    rows.value = details.sort((a,b) => Number(b.plan.id) - Number(a.plan.id)); liquids.value=stock;orders.value=packagingOrders;
    error.value = failures.length ? '部分任务加载失败，请刷新重试：'+failures.join('；') : '';
  } catch (cause) { if (request === sequence) error.value = cause.message || '包装数据加载失败'; }
  finally { if (request === sequence) loading.value = false; }
}
async function selectSource(id) {
  sourceId.value=id;sourceDetail.value=null;draft.value=emptyPackagingDraft();editorError.value='';const request=++sourceSequence;
  if(!id)return;sourceLoading.value=true;
  try{const data=await brewApi.getPlanProgress(id);if(request===sourceSequence)sourceDetail.value=data;}catch(e){if(request===sourceSequence)editorError.value=e.message;}finally{if(request===sourceSequence)sourceLoading.value=false;}
}
function openCreate(row=null) { creating.value=true; selectSource(row?.plan_id || (candidates.value.length===1?candidates.value[0].plan_id:'')); }
function closeCreate(){if(saving.value)return;creating.value=false;++sourceSequence;sourceLoading.value=false;}
async function save(){if(!sourceDetail.value||saving.value)return;saving.value=true;editorError.value='';try{await brewApi.productionPlanAction(sourceId.value,'set-packaging-plan',{version:sourceDetail.value.plan.version,...packagingPayload(draft.value)});creating.value=false;notice.value='包装任务已创建，已分配给指定执行人。';tab.value='tasks';filter.value='pending';await load();}catch(e){editorError.value=e.message;}finally{saving.value=false;}}
async function release(){if(!confirmed.value||saving.value)return;saving.value=true;editorError.value='';try{await brewApi.packagingOrderAction(releaseOrder.value.id,'release',{version:releaseOrder.value.version,confirmed:true});releaseOrder.value=null;notice.value='成品已放行入库。';await load();}catch(e){editorError.value=e.message;}finally{saving.value=false;}}
onMounted(load);
onUnmounted(() => { sequence++; sourceSequence++; });
</script>
<template>
  <section class="packaging-page">
    <header class="pk-heading"><h2>包装与放行</h2><div class="pk-tools"><input v-model.trim="keyword" type="search" aria-label="搜索包装" placeholder="搜索酒款、批次或执行人"><select v-if="tab==='tasks'" v-model="filter" aria-label="包装状态"><option v-for="item in states" :key="item.key" :value="item.key">{{ item.label }}</option><option value="closed">已终止</option></select><button class="btn btn-sm btn-secondary" :disabled="loading" @click="load">刷新</button><button v-if="canManage" class="btn btn-sm btn-primary" :disabled="loading" @click="openCreate()">＋ 新建包装任务</button></div></header>
    <div v-if="error" class="master-error" role="alert">{{ error }}</div><p v-if="notice" class="pk-notice" role="status">{{ notice }}</p>
    <nav class="pk-tabs" aria-label="包装业务"><button v-for="item in tabs" :key="item.key" :class="{active:tab===item.key}" :aria-pressed="tab===item.key" @click="tab=item.key">{{ item.label }}<span>{{ loading?'—':item.count }}</span></button><small v-if="tab==='tasks'">待执行 {{ summary.pending }} · 包装中 {{ summary.running }}</small></nav>
    <div class="pk-content" :aria-busy="loading">
      <template v-if="tab==='tasks'"><div v-if="visible.length" class="pk-table-wrap"><table><thead><tr><th>酒款 / 批次</th><th>包装安排</th><th>执行人</th><th>计划时间</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="row in visible" :key="row.plan.id"><td><strong>{{ row.plan.product?.name }}</strong><small>{{ row.plan.batch?.name || row.plan.name }} · {{ row.plan.factory?.name }}</small></td><td>{{ row.plan.packaging_plan?.packaging_name || '包装材料安排' }}<small v-if="row.plan.packaging_plan?.planned_volume_l">计划包装 {{ number(row.plan.packaging_plan.planned_volume_l) }} L</small></td><td>{{ row.plan.packaging_owner?.name || '待指定' }}</td><td>{{ date(row.plan.packaging_plan?.planned_start) }}</td><td><span class="pk-state" :class="state(row)">{{ label(row) }}</span></td><td><button class="pk-link" @click="selected=row">{{ canExecute(row)?state(row)==='running'?'继续包装':state(row)==='done'?'登记产出':'开始包装':'查看详情' }} →</button></td></tr></tbody></table></div><div v-else class="pk-empty"><h3>{{ loading?'正在加载…':rows.length?'没有匹配的任务':'尚未安排包装任务' }}</h3><template v-if="!loading"><p v-if="candidates.length">有 {{ candidates.length }} 批酿造完成的原液，可选择原液并安排包装。</p><p v-else>酿造完成后，可以从原液批次创建包装任务。</p><button v-if="candidates.length" class="pk-link" @click="tab='raw'">查看待包装原液 →</button></template></div></template>
      <template v-else-if="tab==='raw'"><div v-if="visibleRaw.length" class="pk-table-wrap"><table><thead><tr><th>酒款 / 原液批次</th><th>生产日期</th><th>存放位置</th><th class="pk-numeric">剩余原液</th><th>厂区</th><th></th></tr></thead><tbody><tr v-for="row in visibleRaw" :key="row.batch_id"><td><strong>{{ row.product.name }}</strong><small>{{ row.batch_name }}</small></td><td>{{ row.production_date ? productionDate(row.production_date) : '未记录' }}</td><td>{{ row.tank_verified===false?'位置待核对':row.tank || '未记录位置' }}<small v-if="row.tank_verified===false">计划罐位 {{ row.tank || '—' }}</small></td><td class="pk-numeric"><strong>{{ number(row.on_hand) }} <em>L</em></strong><small v-if="row.volume_basis!=='actual'">计划估算 · 待实测</small></td><td>{{ row.factory.name }}</td><td><button v-if="canManage" class="pk-link" @click="openCreate(row)">安排包装 →</button><button v-else class="pk-link" @click="selected={plan:{id:row.plan_id}}">查看原液 →</button></td></tr></tbody></table></div><div v-else class="pk-empty"><h3>{{ loading?'正在加载…':'暂无可新增任务的原液' }}</h3><p>已安排包装的批次请在“包装任务”中查看。</p></div></template>
      <template v-else><div v-if="visibleOrders.length" class="pk-table-wrap"><table><thead><tr><th>成品 / 包装单</th><th>成品登记</th><th class="pk-numeric">实际产出</th><th>入库位置</th><th></th></tr></thead><tbody><tr v-for="row in visibleOrders" :key="row.id"><td><strong>{{ row.product.name }}</strong><small>{{ row.name }} · {{ row.batch.name }}</small></td><td>{{ row.packaging.name }}</td><td class="pk-numeric">{{ number(row.output_qty) }} {{ unitLabel(row.packaging?.level) }}<small>{{ number(row.output_volume_l) }} L</small></td><td>{{ row.finished_location?.name?.split('/').pop() }}</td><td><button class="pk-link" @click="releaseOrder=row;confirmed=false;editorError=''">{{ canRelease?'核对并放行':'查看详情' }} →</button></td></tr></tbody></table></div><div v-else class="pk-empty"><h3>{{ loading?'正在加载…':'暂无待放行成品' }}</h3><p>包装产出提交后，由有放行权限的人员核对并入库。</p></div></template>
    </div>
    <JourneyDetailDialog v-if="creating" title="新建包装任务" @close="closeCreate"><form id="create-pack-task" @submit.prevent="save"><label class="pk-source-label">选择原液批次<select :value="sourceId" :disabled="saving||loading" required @change="selectSource($event.target.value)"><option value="">选择已酿造完成的原液</option><option v-for="row in candidates" :key="row.plan_id" :value="row.plan_id">{{ row.product.name }} · {{ row.batch_name }} · {{ number(row.on_hand) }} L</option></select></label><p v-if="!candidates.length" class="pk-source-note">暂无可新增任务的原液。已安排的批次可在任务详情中修改安排。</p><div v-if="source" class="pk-source-facts"><span>剩余原液 <strong>{{ number(source.on_hand) }} L</strong></span><span>{{ source.factory.name }} · {{ source.tank_verified===false?'存放位置待核对':source.tank }}</span></div><p v-if="source?.tank_verified===false" class="pk-source-note">可先安排任务，包装前须核对实际罐位及酒液量。</p><p v-if="sourceLoading" class="pk-source-note">正在核对原液批次…</p><PackagingPlanEditor v-if="sourceDetail" v-model="draft" :product-id="sourceDetail.plan.product.id" :factory-id="sourceDetail.plan.factory.id" /><div v-if="editorError" class="master-error" role="alert">{{ editorError }}</div></form><template #footer><button class="btn btn-secondary" :disabled="saving" @click="closeCreate">取消</button><button class="btn btn-primary" type="submit" form="create-pack-task" :disabled="saving||!sourceDetail||sourceLoading">{{ saving?'创建中…':'创建并分配任务' }}</button></template></JourneyDetailDialog>
    <JourneyDetailDialog v-if="releaseOrder" title="成品放行" :subtitle="releaseOrder.name" @close="!saving&&(releaseOrder=null)"><div class="pk-release-facts"><h3>{{ releaseOrder.product.name }}</h3><p>{{ releaseOrder.packaging.name }} · {{ number(releaseOrder.output_qty) }} {{ unitLabel(releaseOrder.packaging?.level) }} / {{ number(releaseOrder.output_volume_l) }} L</p><p>入库位置：{{ releaseOrder.finished_location?.name?.split('/').pop() }}</p><label v-if="canRelease"><input v-model="confirmed" type="checkbox">已核对成品质量、包装数量及入库位置</label><p v-else>由仓库或有放行权限的人员核对后办理入库。</p></div><div v-if="editorError" class="master-error" role="alert">{{ editorError }}</div><template #footer><button class="btn btn-secondary" :disabled="saving" @click="releaseOrder=null">关闭</button><button v-if="canRelease" class="btn btn-primary" :disabled="saving||!confirmed" @click="release">{{ saving?'放行中…':'确认放行入库' }}</button></template></JourneyDetailDialog>
    <ProductionPlanDetail v-if="selected" :plan-id="selected.plan.id" :focus-task-id="selected.task?.id" :initial-stage="selected.task?'packaging':undefined" :allow-execution="!!selected.task" :read-only="selected.task?!selected.task.is_assignee:!canManage" @close="selected=null" @changed="load" />
  </section>
</template>
<style scoped>
.packaging-page{border:1px solid var(--border-default);border-radius:9px;min-width:0;overflow:hidden;background:var(--bg-surface)}.pk-heading{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:18px 20px;flex-wrap:wrap}.pk-heading h2{font-size:17px;margin:0;white-space:nowrap}.pk-tools{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-left:auto}.pk-tools :is(input,select,.btn){box-sizing:border-box;height:34px;min-height:34px;border-radius:6px;padding:0 11px;font:inherit;font-size:12px}.pk-tools :is(input,select){background:var(--bg-input);border:1px solid var(--border-default);color:var(--text-primary);color-scheme:dark}.pk-tools input{width:220px}.pk-tools select{width:116px}.pk-tabs{display:flex;gap:24px;align-items:center;padding:0 20px;border-bottom:1px solid var(--border-default)}.pk-tabs button{display:flex;gap:8px;align-items:center;border:0;border-bottom:2px solid transparent;border-radius:0;padding:13px 0;background:none;color:var(--text-muted);font:inherit;font-size:13px;cursor:pointer;white-space:nowrap}.pk-tabs button.active{border-color:var(--accent-gold);color:var(--text-primary)}.pk-tabs button span{font-size:11px;font-variant-numeric:tabular-nums;color:var(--text-muted)}.pk-tabs small{margin-left:auto;color:var(--text-muted);font-size:11px}.pk-table-wrap{overflow:auto}.pk-table-wrap table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}.pk-table-wrap th{font-size:11px;font-weight:400;color:var(--text-muted);background:#ffffff02;padding:12px 20px;white-space:nowrap}.pk-table-wrap td{padding:16px 20px;border-top:1px solid var(--border-default);max-width:300px;line-height:1.5}.pk-table-wrap td:last-child{white-space:nowrap;text-align:right}.pk-table-wrap td strong{font-weight:600;font-size:13px;display:block}.pk-table-wrap small{display:block;color:var(--text-muted);font-size:11px;margin-top:5px}.pk-table-wrap em{font-style:normal;font-size:11px;font-weight:400;color:var(--text-muted)}.pk-table-wrap .pk-numeric{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}.pk-state{font-size:11px;white-space:nowrap;color:var(--text-muted)}.pk-state.pending,.pk-state.running{color:var(--accent-gold)}.pk-state.done{color:#93ba8b}.pk-link{padding:0;border:0;background:none;color:var(--accent-gold);font:inherit;font-size:12px;cursor:pointer;white-space:nowrap}.pk-empty{padding:46px 20px 50px;text-align:center}.pk-empty h3{font-size:14px;font-weight:500;margin:0 0 10px}.pk-empty p,.pk-source-note,.pk-release-facts p{color:var(--text-muted);font-size:12px;line-height:1.8;margin:0 0 14px}.pk-source-label{display:grid;gap:8px;font-size:12px}.pk-source-label select{width:100%;height:38px;background:var(--bg-input);color:var(--text-primary);border:1px solid var(--border-default);border-radius:6px;padding:0 10px;font:inherit;font-size:12px}.pk-source-facts{display:flex;gap:16px;justify-content:space-between;flex-wrap:wrap;font-size:12px;color:var(--text-muted);margin:18px 0 12px}.pk-source-facts strong{color:var(--text-primary);margin-left:8px;font-size:18px}.pk-release-facts h3{font-size:17px}.pk-release-facts label{display:flex;gap:8px;align-items:center;font-size:12px;margin-top:24px}.pk-notice{margin:0 20px 12px;font-size:12px;color:#93ba8b}.pk-content[aria-busy=true]{opacity:.65}.packaging-page :deep(footer .btn+.btn){margin-left:8px}.packaging-page button:focus-visible{outline:2px solid var(--accent-gold);outline-offset:3px}@media(max-width:760px){.pk-heading{padding:16px}.pk-tools{width:100%}.pk-tools input{flex:1;min-width:130px;width:160px}.pk-tabs{gap:18px;padding:0 16px;overflow:auto}.pk-tabs small{display:none}.pk-table-wrap :is(td,th){padding:12px 14px}.pk-table-wrap table{min-width:700px}.pk-empty{padding:34px 16px}}
</style>
